use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut keys: Vec<int> = []
    let mut lf: Vec<int> = []
    let mut rt: Vec<int> = []
    let mut root: int = -1
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        let cmd = parts[0]
        let mut x: int = 0
        if parts.len() > 1 {
            x = parts[1].parse::<int>().unwrap_or(0)
        }
        if cmd == "insert" {
            let mut cur = root
            let mut par: int = -1
            let mut left = false
            let mut found = false
            while cur != -1 {
                par = cur
                if keys[cur as usize] == x {
                    found = true
                    break
                }
                if x < keys[cur as usize] {
                    left = true
                    cur = lf[cur as usize]
                } else {
                    left = false
                    cur = rt[cur as usize]
                }
            }
            if found {
                println("dup")
            } else {
                let idx = keys.len() as int
                keys.push(x)
                lf.push(-1)
                rt.push(-1)
                if par == -1 {
                    root = idx
                } else if left {
                    lf[par as usize] = idx
                } else {
                    rt[par as usize] = idx
                }
                println("ok")
            }
        } else if cmd == "contains" {
            let mut cur = root
            let mut found = false
            while cur != -1 {
                if keys[cur as usize] == x {
                    found = true
                    break
                }
                if x < keys[cur as usize] {
                    cur = lf[cur as usize]
                } else {
                    cur = rt[cur as usize]
                }
            }
            if found {
                println("yes")
            } else {
                println("no")
            }
        } else if cmd == "delete" {
            let mut cur = root
            let mut par: int = -1
            let mut left = false
            let mut found = false
            while cur != -1 {
                if keys[cur as usize] == x {
                    found = true
                    break
                }
                par = cur
                if x < keys[cur as usize] {
                    left = true
                    cur = lf[cur as usize]
                } else {
                    left = false
                    cur = rt[cur as usize]
                }
            }
            if !found {
                println("missing")
            } else {
                if lf[cur as usize] != -1 && rt[cur as usize] != -1 {
                    let mut sp = cur
                    let mut s = rt[cur as usize]
                    let mut sleft = false
                    while lf[s as usize] != -1 {
                        sp = s
                        s = lf[s as usize]
                        sleft = true
                    }
                    keys[cur as usize] = keys[s as usize]
                    cur = s
                    par = sp
                    left = sleft
                }
                let mut c = lf[cur as usize]
                if c == -1 {
                    c = rt[cur as usize]
                }
                if par == -1 {
                    root = c
                } else if left {
                    lf[par as usize] = c
                } else {
                    rt[par as usize] = c
                }
                println("ok")
            }
        } else if cmd == "inorder" {
            if root == -1 {
                println("<empty>")
            } else {
                let mut out: Vec<string> = []
                let mut stack: Vec<int> = []
                let mut cur = root
                while cur != -1 || stack.len() > 0 {
                    while cur != -1 {
                        stack.push(cur)
                        cur = lf[cur as usize]
                    }
                    let n = stack.pop().unwrap_or(0)
                    out.push("${keys[n as usize]}")
                    cur = rt[n as usize]
                }
                println(out.join(" "))
            }
        } else if cmd == "height" {
            let mut h: int = 0
            let mut level: Vec<int> = []
            if root != -1 {
                level.push(root)
            }
            while level.len() > 0 {
                h += 1
                let mut next: Vec<int> = []
                for n in level {
                    if lf[n as usize] != -1 {
                        next.push(lf[n as usize])
                    }
                    if rt[n as usize] != -1 {
                        next.push(rt[n as usize])
                    }
                }
                level = next
            }
            println("${h}")
        } else if cmd == "min" {
            if root == -1 {
                println("empty")
            } else {
                let mut cur = root
                while lf[cur as usize] != -1 {
                    cur = lf[cur as usize]
                }
                println("${keys[cur as usize]}")
            }
        } else if cmd == "max" {
            if root == -1 {
                println("empty")
            } else {
                let mut cur = root
                while rt[cur as usize] != -1 {
                    cur = rt[cur as usize]
                }
                println("${keys[cur as usize]}")
            }
        }
    }
}

